import React from 'react';

/** Size preset for the Avatar. */
export type AvatarSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';

/** Props for the {@link Avatar} component. */
export interface AvatarProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Image source URL. When absent, the fallback is rendered. */
  src?: string;
  /** Alt text for the image. */
  alt?: string;
  /** Fallback text (typically initials) shown when there is no image. */
  fallback?: string;
  /** Size preset. */
  size?: AvatarSize;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * User image with dither fallback.
 * Renders a `<div>` with the `sk-avatar` class, containing either an `<img>` or fallback text.
 */
export const Avatar = React.forwardRef<HTMLDivElement, AvatarProps>(
  ({ src, alt, fallback, size = 'md', className, ...rest }, ref) => (
    <div
      ref={ref}
      className={`sk-avatar${className ? ` ${className}` : ''}`}
      data-size={size}
      {...rest}
    >
      {src ? (
        <img src={src} alt={alt ?? ''} />
      ) : (
        <span className="sk-avatar__fallback">{fallback}</span>
      )}
    </div>
  ),
);

Avatar.displayName = 'Avatar';

/**
 * skeehn — Avatar Component
 *
 * @component sk-avatar
 * @sizes     xs | sm | md (default) | lg | xl
 * @variants  default | pixel | retro | ascii
 * @slots     img | __fallback
 * @a11y      alt text on img, fallback initials, focus ring when actionable
 */

.sk-avatar {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  overflow: hidden; border-radius: var(--sk-radius);
  border: 2px solid hsl(var(--sk-border-color));
  font-family: var(--sk-font-mono);
  transition: transform var(--sk-transition), box-shadow var(--sk-transition);
}
.sk-avatar:focus-visible { outline: var(--sk-focus-ring); outline-offset: var(--sk-focus-ring-offset); }
.sk-avatar:hover { transform: translateY(-1px); box-shadow: 0 2px 4px hsl(0 0% 0% / 0.2); }
.sk-avatar img { width: 100%; height: 100%; object-fit: cover; }
.sk-avatar__fallback {
  display: flex; align-items: center; justify-content: center; width: 100%; height: 100%;
  font-weight: 600; color: hsl(var(--sk-foreground)); background: hsl(var(--sk-secondary));
  position: relative; letter-spacing: var(--sk-letter-spacing-wide);
}
.sk-avatar__fallback::before { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: var(--sk-dither-opacity); pointer-events: none; }

/* Sizes (tokenized) */
.sk-avatar[data-size="xs"] { width: var(--sk-size-avatar-xs); height: var(--sk-size-avatar-xs); font-size: 0.5rem; }
.sk-avatar[data-size="sm"] { width: var(--sk-size-avatar-sm); height: var(--sk-size-avatar-sm); font-size: var(--sk-font-size-xs); }
.sk-avatar[data-size="md"] { width: var(--sk-size-avatar-md); height: var(--sk-size-avatar-md); font-size: var(--sk-font-size-sm); }
.sk-avatar[data-size="lg"] { width: var(--sk-size-avatar-lg); height: var(--sk-size-avatar-lg); font-size: var(--sk-font-size-base); }
.sk-avatar[data-size="xl"] { width: var(--sk-size-avatar-xl); height: var(--sk-size-avatar-xl); font-size: var(--sk-font-size-lg); }

/* Pixel variant */
.sk-avatar[data-variant="pixel"] { border: 2px solid hsl(var(--sk-foreground)); box-shadow: 2px 2px 0 hsl(var(--sk-foreground)); border-radius: 0; }
/* Retro variant */
.sk-avatar[data-variant="retro"] { box-shadow: 0 0 6px hsl(var(--sk-primary) / 0.2); }
/* ASCII variant */
.sk-avatar[data-variant="ascii"] { border: none; background: transparent; }
.sk-avatar[data-variant="ascii"] .sk-avatar__fallback { background: transparent; border: 1px dashed hsl(var(--sk-border-color)); }

/* Loading */
@keyframes sk-avatar-dither { 0%, 100% { opacity: 0.1; } 50% { opacity: 0.25; } }
.sk-avatar[data-loading] .sk-avatar__fallback::before { animation: sk-avatar-dither 1.5s ease-in-out infinite; }

/* Skeleton (centralized keyframe) */
.sk-avatar[data-skeleton] { border-color: hsl(var(--sk-border-color)); }
.sk-avatar[data-skeleton] .sk-avatar__fallback {
  color: transparent;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-secondary)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%; animation: sk-shimmer 1.8s ease-in-out infinite;
}

@media print {
  .sk-avatar { box-shadow: none; border: 1px solid hsl(var(--sk-foreground)); }
  .sk-avatar[data-skeleton] { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .sk-avatar { transition: none; }
  .sk-avatar:hover { transform: none; }
  .sk-avatar[data-loading] .sk-avatar__fallback::before { animation: none; }
  .sk-avatar[data-skeleton] .sk-avatar__fallback { animation: none; background: hsl(var(--sk-muted)); }
}
